// static
bool StructTraits<::ash::libassistant::mojom::AssistantTimer::DataView, ::ash::libassistant::mojom::AssistantTimerPtr>::Read(
    ::ash::libassistant::mojom::AssistantTimer::DataView input,
    ::ash::libassistant::mojom::AssistantTimerPtr* output) {
  bool success = true;
  ::ash::libassistant::mojom::AssistantTimerPtr result(::ash::libassistant::mojom::AssistantTimer::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadLabel(&result->label))
        success = false;
      if (success && !input.ReadFireTime(&result->fire_time))
        success = false;
      if (success && !input.ReadOriginalDuration(&result->original_duration))
        success = false;
      if (success && !input.ReadRemainingTime(&result->remaining_time))
        success = false;
      if (success && !input.ReadState(&result->state))
        success = false;
  *output = std::move(result);
  return success;
}

